files.content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

[hidden] {
  display: none !important;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  background: #1e1e2f;
  color: #e0e0e0;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 16px;
}

.card {
  background: #2a2a3d;
  border-radius: 16px;
  padding: 24px;
  max-width: 600px;
  width: 100%;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
}

header {
  margin-bottom: 24px;
  text-align: center;
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  color: #f0c040;
  margin-bottom: 4px;
}

.subtitle {
  color: #a0a0b0;
  font-size: 1rem;
}

h2 {
  font-size: 1.25rem;
  font-weight: 600;
  margin-bottom: 12px;
  color: #d0d0e0;
}

.income-section {
  margin-bottom: 24px;
}

.income-section label {
  display: block;
  font-weight: 600;
  margin-bottom: 4px;
  color: #c0c0d0;
}

.income-section input {
  width: 100%;
  padding: 12px;
  font-size: 1.125rem;
  border: 2px solid #3a3a50;
  border-radius: 8px;
  background: #1e1e2f;
  color: #e0e0e0;
  transition: border-color 0.2s, box-shadow 0.2s;
}

.income-section input:focus {
  outline: none;
  border-color: #f0c040;
  box-shadow: 0 0 0 3px rgba(240, 192, 64, 0.3);
}

.help-text {
  display: block;
  font-size: 0.875rem;
  color: #808090;
  margin-top: 4px;
}

.expense-section {
  margin-bottom: 24px;
}

.expense-form {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  align-items: flex-end;
}

.form-group {
  flex: 1 1 120px;
  display: flex;
  flex-direction: column;
}

.form-group label {
  font-weight: 600;
  margin-bottom: 4px;
  color: #c0c0d0;
}

.form-group select,
.form-group input {
  padding: 10px;
  font-size: 1rem;
  border: 2px solid #3a3a50;
  border-radius: 8px;
  background: #1e1e2f;
  color: #e0e0e0;
  transition: border-color 0.2s, box-shadow 0.2s;
}

.form-group select:focus,
.form-group input:focus {
  outline: none;
  border-color: #f0c040;
  box-shadow: 0 0 0 3px rgba(240, 192, 64, 0.3);
}

.btn-add {
  padding: 10px 20px;
  font-size: 1rem;
  font-weight: 600;
  background: #f0c040;
  color: #1e1e2f;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
  flex: 0 0 auto;
  width: 100%;
}

.btn-add:hover {
  background: #e0b030;
}

.btn-add:focus-visible {
  outline: 3px solid #f0c040;
  outline-offset: 2px;
}

.btn-add:active {
  transform: scale(0.97);
}

.summary-section {
  background: #1e1e2f;
  border-radius: 12px;
  padding: 16px;
  margin-bottom: 24px;
  text-align: center;
}

.summary-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
}

.summary-label {
  font-size: 1.125rem;
  font-weight: 600;
  color: #c0c0d0;
}

.summary-value {
  font-size: 1.5rem;
  font-weight: 700;
  color: #4caf50;
  transition: color 0.2s;
}

.summary-value.negative {
  color: #f44336;
}

.bars-section {
  margin-bottom: 0;
}

.bars-container {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.bar-row {
  display: flex;
  align-items: center;
  gap: 8px;
}

.bar-label {
  flex: 0 0 60px;
  font-weight: 600;
  font-size: 0.9375rem;
  color: #c0c0d0;
}

.bar-track {
  flex: 1;
  height: 24px;
  background: #1e1e2f;
  border-radius: 12px;
  overflow: hidden;
}

.bar-fill {
  height: 100%;
  background: #f0c040;
  border-radius: 12px;
  transition: width 0.3s ease;
  min-width: 0;
}

.bar-amount {
  flex: 0 0 70px;
  text-align: right;
  font-size: 0.9375rem;
  font-weight: 600;
  color: #d0d0e0;
}

@media (max-width: 480px) {
  .card {
    padding: 16px;
  }
  h1 {
    font-size: 1.5rem;
  }
  .bar-label {
    flex: 0 0 50px;
    font-size: 0.875rem;
  }
  .bar-amount {
    flex: 0 0 60px;
    font-size: 0.875rem;
  }
  .summary-value {
    font-size: 1.25rem;
  }
}

const state = {
  income: 0,
  expenses: []
};

const incomeInput = document.getElementById('income');
const expenseForm = document.getElementById('expense-form');
const categorySelect = document.getElementById('category');
const amountInput = document.getElementById('amount');
const remainingEl = document.getElementById('remaining');
const barsContainer = document.getElementById('bars-container');

function updateRemaining() {
  const totalExpenses = state.expenses.reduce((sum, e) => sum + e.amount, 0);
  const remaining = state.income - totalExpenses;
  remainingEl.textContent = `$${remaining.toFixed(2)}`;
  remainingEl.classList.toggle('negative', remaining < 0);
}

function updateBars() {
  const categories = ['Food', 'Rent', 'Fun', 'Other'];
  const totals = {};
  categories.forEach(c => totals[c] = 0);
  state.expenses.forEach(e => {
    if (totals[e.category] !== undefined) {
      totals[e.category] += e.amount;
    }
  });
  const maxTotal = Math.max(...Object.values(totals), 1);
  barsContainer.innerHTML = '';
  categories.forEach(cat => {
    const amount = totals[cat];
    const percent = (amount / maxTotal) * 100;
    const row = document.createElement('div');
    row.className = 'bar-row';
    row.innerHTML = `
      <span class="bar-label">${cat}</span>
      <div class="bar-track"><div class="bar-fill" style="width: ${percent}%"></div></div>
      <span class="bar-amount">$${amount.toFixed(2)}</span>
    `;
    barsContainer.appendChild(row);
  });
}

function updateAll() {
  updateRemaining();
  updateBars();
}

incomeInput.addEventListener('input', () => {
  const val = parseFloat(incomeInput.value);
  state.income = isNaN(val) || val < 0 ? 0 : val;
  updateAll();
});

expenseForm.addEventListener('submit', (e) => {
  e.preventDefault();
  const amount = parseFloat(amountInput.value);
  if (isNaN(amount) || amount <= 0) {
    amountInput.focus();
    return;
  }
  state.expenses.push({
    category: categorySelect.value,
    amount: amount
  });
  amountInput.value = '';
  amountInput.focus();
  updateAll();
});

updateAll();
